'use strict';
const $=s=>document.querySelector(s);
const state={mode:null,phase:'setup',latest:null,calibrated:false,validation:null,samples:[],started:0,elapsed:0,running:false,raf:0,epoch:0,viewport:null};
let targetTimer,validationRows=[],activeValidation=null,calIndex=0,calClicks=0,lastSample=0,lastTick=0;
const calibration=[[.1,.18],[.5,.18],[.9,.18],[.1,.5],[.5,.5],[.9,.5],[.1,.82],[.5,.82],[.9,.82]];
const checks=[[.25,.3],[.75,.3],[.5,.55],[.25,.72],[.75,.72]];
const quantile=(a,q)=>{if(!a.length)return null;const s=[...a].sort((a,b)=>a-b);return s[Math.min(s.length-1,Math.floor((s.length-1)*q))]};
const fmt=n=>n==null?'—':Math.round(n)+' px';
function phase(p,n){state.phase=p;document.querySelectorAll('.steps span').forEach((s,i)=>s.classList.toggle('selected',i===n-1));}
function message(s){$('#signal').textContent=s;}
function setDesk(html){$('#desk').innerHTML=html;}
function setup(){phase('setup',1);setDesk(`<div class="welcome"><div class="eyebrow">EXPERIMENT NO. 001</div><h2>Where does a learner look?</h2><p>A short reading experiment, a simple webcam, and a transparent look at the quality of the signal.</p><label class="consent"><input id="consent" type="checkbox"><span>I agree to enable my camera for this exploratory demo. Frames are processed locally; nothing is recorded or uploaded by this app. Tracking assets load from this site.</span></label><div class="actions"><button class="solid" id="camera" disabled>Connect camera ↗</button><button class="secondary" id="rehearse">Rehearse with pointer →</button></div><p class="small-note">ABOUT 3 MINUTES · DESKTOP RECOMMENDED · ADULT TESTING</p><div id="error" role="status"></div></div>`);$('#consent').onchange=e=>$('#camera').disabled=!e.target.checked;$('#camera').onclick=startCamera;$('#rehearse').onclick=()=>startMode('pointer');}
let trackerPromise;
function timeoutError(stage){const e=new Error(stage+' timed out');e.name='TimeoutError';return e;}
function withTimeout(promise,ms,stage){let timer;return Promise.race([promise,new Promise((_,reject)=>{timer=setTimeout(()=>reject(timeoutError(stage)),ms);})]).finally(()=>clearTimeout(timer));}
function stopCamera(){
  const video=document.getElementById('webgazerVideoFeed');
  if(video?.srcObject){video.srcObject.getTracks().forEach(track=>track.stop());video.srcObject=null;}
  try{window.webgazer?.removeMouseEventListeners();window.webgazer?.end();}catch{/* A failed start may not have created the preview. */}
  document.querySelectorAll('#webgazerVideoContainer,#webgazerGazeDot').forEach(el=>el.remove());
}
function cameraFailure(error,stage){
  const name=error?.name||'Error';
  if(name==='NotAllowedError'||name==='PermissionDeniedError'||name==='SecurityError')return 'Camera access was blocked. Open this link in Chrome or Edge in a separate browser window, allow camera access for this site, and check Windows Settings → Privacy & security → Camera if it is still blocked.';
  if(name==='NotFoundError'||name==='DevicesNotFoundError')return 'No camera was found. Connect or enable your webcam, then reload and try again.';
  if(name==='NotReadableError'||name==='TrackStartError')return 'The camera could not be opened. Close other apps using it (such as a video meeting), check the webcam privacy switch, then reload and try again.';
  if(name==='OverconstrainedError')return 'This camera could not use the requested settings. Try another webcam or a desktop browser.';
  if(name==='TimeoutError')return 'Startup took too long during '+stage+'. If no camera prompt appeared, open the site in Chrome or Edge outside this embedded browser. Otherwise check camera permission, then reload to retry.';
  if(name==='UnsupportedError')return 'This browser does not expose camera access. Open the same link directly in Chrome or Edge on your computer.';
  return 'Tracking could not initialize during '+stage+'. Reload to retry. If you are using an embedded browser, open this link directly in Chrome or Edge.';
}
function loadTracker(){
  if(window.webgazer)return Promise.resolve();
  if(trackerPromise)return trackerPromise;
  trackerPromise=withTimeout(new Promise((resolve,reject)=>{const script=document.createElement('script');script.src='vendor/webgazer.js';script.onload=resolve;script.onerror=()=>reject(new Error('Tracking library download failed'));document.head.append(script);}),20000,'tracking library').catch(error=>{trackerPromise=null;throw error;});
  return trackerPromise;
}
async function startCamera(){
  const epoch=++state.epoch;let stage='browser camera support';
  const button=$('#camera');button.disabled=true;button.textContent='Checking camera…';$('#rehearse').disabled=true;$('#error').textContent='';
  try{
    if(!window.isSecureContext||!navigator.mediaDevices?.getUserMedia){const error=new Error('Camera API unavailable');error.name='UnsupportedError';throw error;}
    const policy=document.permissionsPolicy||document.featurePolicy;
    if(policy?.allowsFeature&&!policy.allowsFeature('camera')){const error=new Error('Camera blocked by browser embedding policy');error.name='SecurityError';throw error;}
    stage='tracking library loading';await loadTracker();if(epoch!==state.epoch)return;
    // This WebGazer distribution uses a relative MediaPipe directory by default.
    // Ship the matching assets with the application and resolve from the page URL.
    webgazer.params.faceMeshSolutionPath=new URL('mediapipe/face_mesh/',document.baseURI).href;
    webgazer.saveDataAcrossSessions(false);await webgazer.setCameraConstraints({audio:false,video:{width:{ideal:640},height:{ideal:480},facingMode:'user'}});
    webgazer.setRegression('ridge').setGazeListener(data=>{if(state.mode==='camera')state.latest=data?{x:data.x,y:data.y,t:performance.now()}:null;});
    stage='camera permission and face-tracking initialization';button.textContent='Allow camera to continue…';$('#error').textContent='Allow camera access when prompted. Initializing the local tracking model can take a few seconds.';
    const startup=Promise.resolve(webgazer.begin());
    startup.then(()=>{if(epoch!==state.epoch)stopCamera();},()=>{});
    await withTimeout(startup,45000,stage);
    if(epoch!==state.epoch){stopCamera();return;}
    webgazer.removeMouseEventListeners();webgazer.showPredictionPoints(false);webgazer.showVideoPreview(true);startMode('camera');
  }catch(error){
    if(epoch!==state.epoch)return;
    state.epoch++;stopCamera();
    console.warn('Faraday camera startup:',stage,error?.name,error?.message);
    $('#error').textContent=cameraFailure(error,stage)+' You can still rehearse the workflow with the pointer.';
    button.disabled=false;button.textContent='Reload & retry camera ↗';button.onclick=()=>location.reload();$('#rehearse').disabled=false;
  }
}
function startMode(mode){if(mode==='pointer')stopCamera();state.mode=mode;state.latest=null;$('#modeBadge').textContent=mode==='camera'?'LIVE WEBCAM':'POINTER REHEARSAL';$('#source').textContent=mode==='camera'?'Webcam estimate':'Pointer (not gaze)';message('○ Ready to calibrate');showCalibrationIntro();}
document.addEventListener('pointermove',e=>{if(state.mode==='pointer')state.latest={x:e.clientX,y:e.clientY,t:performance.now()};});
function showCalibrationIntro(){phase('calibration',2);setDesk(`<div class="welcome"><div class="eyebrow">01 / FIND YOUR BEARINGS</div><h2>Nine points. One steady position.</h2><p>${state.mode==='camera'?'Look directly at each orange target and click it five times. Keep your eyes on the target as you click.':'This is pointer rehearsal, not eye tracking. Move to each target and click five times to practise the workflow.'}</p><p>The targets fill the browser window. Stay in the same position and keep this window size throughout the experiment.</p><div class="actions"><button class="solid" id="calibrate">Begin calibration →</button><button class="secondary" id="reset">Start over</button></div></div>`);$('#calibrate').onclick=beginCalibration;$('#reset').onclick=reset;}
function placeTarget(pt){$('#target').style.left=pt[0]*innerWidth+'px';$('#target').style.top=pt[1]*innerHeight+'px';}
function beginCalibration(){state.viewport={width:innerWidth,height:innerHeight,dpr:devicePixelRatio};state.calibrated=false;state.validation=null;$('#accuracy').textContent='—';if(state.mode==='camera')webgazer.clearData();calIndex=0;calClicks=0;$('#overlay').hidden=false;$('#target').disabled=false;$('#target').onclick=clickCalibration;calTarget();}
function calTarget(){placeTarget(calibration[calIndex]);$('#targetInstruction').textContent=`Calibration ${calIndex+1}/9 · ${state.mode==='pointer'?'Pointer rehearsal':'Look at the target and click five times'}`;$('#targetProgress').textContent=`${calClicks}/5 clicks · Keep your head still`;}
function clickCalibration(e){if(state.mode==='camera'){const r=e.currentTarget.getBoundingClientRect();webgazer.recordScreenPosition(r.left+r.width/2,r.top+r.height/2,'click');}calClicks++;if(calClicks===5){calIndex++;calClicks=0;}if(calIndex===9){$('#overlay').hidden=true;state.calibrated=true;$('#calStatus').textContent=state.mode==='pointer'?'Rehearsed 9/9':'9/9 complete';showValidationIntro();}else calTarget();}
function showValidationIntro(){phase('validation',3);setDesk(`<div class="welcome"><div class="eyebrow">02 / TRUST THE SIGNAL?</div><h2>Let’s measure the uncertainty.</h2><p>Five new targets, three seconds each. ${state.mode==='camera'?'Look at the centre of each target without clicking. These samples will not train the model.':'Move your pointer to each target and hold it steady. This only tests the presentation workflow.'}</p><p>We measure the distance between the estimate and the target, including missing-sample periods. No signal means no usable accuracy result.</p><div class="actions"><button class="solid" id="validate">Run accuracy check →</button><button class="secondary" id="recalibrate">Recalibrate</button></div></div>`);$('#validate').onclick=beginValidation;$('#recalibrate').onclick=showCalibrationIntro;}
function beginValidation(){validationRows=[];$('#overlay').hidden=false;$('#target').disabled=true;$('#target').onclick=null;runCheck(0);}
function runCheck(i){if(i===checks.length){activeValidation=null;$('#overlay').hidden=true;finishValidation();return;}placeTarget(checks[i]);$('#targetInstruction').textContent=`Accuracy check ${i+1}/5 · ${state.mode==='camera'?'Look at the target; do not click':'Hold the pointer on the target'}`;$('#targetProgress').textContent='Settle for 1 second, then hold for 3 seconds';activeValidation=null;targetTimer=setTimeout(()=>{activeValidation={i,target:{x:checks[i][0]*innerWidth,y:checks[i][1]*innerHeight},started:performance.now(),attempts:0,errors:[]};targetTimer=setTimeout(()=>{validationRows.push(activeValidation);activeValidation=null;runCheck(i+1);},3000);},1000);}
function fresh(){const p=state.latest;return p&&Number.isFinite(p.x)&&Number.isFinite(p.y)&&performance.now()-p.t<(state.mode==='pointer'?Infinity:250)?p:null;}
setInterval(()=>{if(!activeValidation||document.hidden)return;const p=fresh();activeValidation.attempts++;if(p)activeValidation.errors.push(Math.hypot(p.x-activeValidation.target.x,p.y-activeValidation.target.y));},50);
function finishValidation(){const errors=validationRows.flatMap(r=>r.errors);const attempts=validationRows.reduce((n,r)=>n+r.attempts,0);const availability=attempts?errors.length/attempts:0;const median=quantile(errors,.5),p90=quantile(errors,.9);const pass=median!==null&&median<=120&&availability>=.7&&validationRows.every(r=>r.errors.length>=10);state.validation={mode:state.mode,median,p90,availability,pass,targets:validationRows,viewport:state.viewport,checkedAt:new Date().toISOString()};$('#accuracy').textContent=fmt(median);message(pass?'● Check complete':'○ Recalibration recommended');phase('validated',3);setDesk(`<div class="welcome"><div class="eyebrow">ACCURACY CHECK / ${state.mode==='pointer'?'REHEARSAL ONLY':pass?'PROVISIONAL PASS':'NEEDS REVIEW'}</div><h2>${state.mode==='pointer'?'Workflow checked. Gaze untested.':pass?'Ready for a broad view.':'The signal needs another look.'}</h2><div class="stats"><div><b>${fmt(median)}</b><span>MEDIAN ERROR</span></div><div><b>${fmt(p90)}</b><span>90TH PERCENTILE</span></div><div><b>${Math.round(availability*100)}%</b><span>SAMPLE AVAILABILITY</span></div></div><p>${state.mode==='pointer'?'Pointer precision says nothing about webcam accuracy. All exports will be labelled as pointer rehearsal.':'Prototype gate: median ≤120 px, ≥70% availability, and ≥10 samples at every target. A pass supports exploratory broad regions only.'}</p><div class="actions"><button class="solid" id="learn">${pass||state.mode==='pointer'?'Continue to activity':'Continue with low-quality flag'} →</button><button class="secondary" id="recalibrate">Recalibrate</button></div></div>`);$('#learn').onclick=showActivity;$('#recalibrate').onclick=showCalibrationIntro;}
const lesson=()=>`<div class="activity" id="activity"><div class="activity-inner"><article data-region="reading"><div class="eyebrow">A SHORT LESSON / NATURAL SYSTEMS</div><h2>The quiet work of a leaf.</h2><p>A leaf is a small solar workshop. It absorbs light and uses that energy to turn water and carbon dioxide into sugars.</p><p>Those sugars help a plant grow. Oxygen is released along the way. The same process connects sunlight to much of the food we eat.</p><p><b>Consider:</b> What changes when a plant gets less light?</p></article><div class="diagram" data-region="diagram"><svg viewBox="0 0 180 150" aria-label="Sunlight reaches a leaf"><g fill="none" stroke="#c95632" stroke-width="2"><circle cx="90" cy="26" r="15"/><path d="M90 2v6m0 36v8m-30-26h8m44 0h8M68 5l5 6m34 30 5 6m0-42-5 6M73 41l-5 6M90 60v22"/></g><path d="M90 133C35 134 38 73 44 73c40-1 54 23 46 60Z" fill="#73876a"/><path d="M90 133c-6-45 22-59 54-60 6 34-16 61-54 60Z" fill="#365e4e"/><path d="M90 144V105m0 24-29-32m29 26 35-29" fill="none" stroke="#d9dec8" stroke-width="2"/></svg><p>LIGHT + WATER + CO₂<br>↓<br>SUGAR + OXYGEN</p></div></div><canvas id="heatmap" hidden></canvas></div>`;
function showActivity(){phase('ready',4);setDesk(`<div class="actions"><button class="solid" id="start">Start 45-second observation →</button><button class="secondary" id="redo">Check accuracy again</button></div>${lesson()}<p class="small-note">READ NATURALLY · KEEP THIS WINDOW STEADY · BROAD REGIONS ONLY</p>`);$('#start').onclick=startRecording;$('#redo').onclick=showValidationIntro;}
function startRecording(){state.samples=[];state.elapsed=0;state.started=performance.now();state.running=true;state.viewport={width:innerWidth,height:innerHeight,dpr:devicePixelRatio};state.activityRect=rectJSON($('#activity').getBoundingClientRect());state.regions=[...document.querySelectorAll('[data-region]')].map(e=>({name:e.dataset.region,rect:rectJSON(e.getBoundingClientRect())}));$('#start').outerHTML='<button class="secondary" id="pause">Pause</button><button class="solid" id="finish">Finish & review →</button><span id="clock">00:45</span>';$('#redo').hidden=true;$('#pause').onclick=togglePause;$('#finish').onclick=finish;lastTick=performance.now();message('● Recording observations');}
function rectJSON(r){return{x:r.x,y:r.y,width:r.width,height:r.height};}
function inside(p,r){return p.x>=r.x&&p.x<=r.x+r.width&&p.y>=r.y&&p.y<=r.y+r.height;}
function togglePause(){state.running=!state.running;lastTick=performance.now();$('#pause').textContent=state.running?'Pause':'Resume';message(state.running?'● Recording observations':'○ Paused');}
function tick(now){if(state.running){state.elapsed+=Math.min(250,now-lastTick);if(now-lastSample>=50){state.activityRect=rectJSON($('#activity').getBoundingClientRect());state.regions=[...document.querySelectorAll('[data-region]')].map(e=>({name:e.dataset.region,rect:rectJSON(e.getBoundingClientRect())}));const p=fresh();const valid=!!p;const offscreen=valid&&(p.x<0||p.x>innerWidth||p.y<0||p.y>innerHeight);state.samples.push({t_ms:Math.round(state.elapsed),x:valid?Math.round(p.x):null,y:valid?Math.round(p.y):null,valid,offscreen,activity_x:valid?p.x-state.activityRect.x:null,activity_y:valid?p.y-state.activityRect.y:null,region:valid?state.regions.find(r=>inside(p,r.rect))?.name||'outside activity':'missing'});$('#sampleCount').textContent=state.samples.length;lastSample=now;}if($('#clock'))$('#clock').textContent='00:'+String(Math.max(0,Math.ceil((45000-state.elapsed)/1000))).padStart(2,'0');if(state.elapsed>=45000)finish();}lastTick=now;state.raf=requestAnimationFrame(tick);}
function finish(){state.running=false;phase('review',5);$('#gazeDot').hidden=true;const valid=state.samples.filter(s=>s.valid);const a=state.samples.length?valid.length/state.samples.length:0;setDesk(`<div class="welcome" style="padding-bottom:0"><div class="eyebrow">SESSION REVIEW / ${state.mode==='pointer'?'POINTER REHEARSAL':'WEBCAM ESTIMATES'}</div><h2>Traces, not conclusions.</h2><div class="stats"><div><b>${(state.elapsed/1000).toFixed(1)}s</b><span>ACTIVE TIME</span></div><div><b>${Math.round(a*100)}%</b><span>AVAILABLE SAMPLES</span></div><div><b>${state.samples.filter(s=>s.offscreen).length}</b><span>OFFSCREEN ESTIMATES</span></div></div><div class="notice">${state.mode==='pointer'?'This is pointer rehearsal data. It does not represent eye movements.':!state.validation?.pass?'Accuracy check did not pass. Treat these observations as low quality.':'Exploratory estimates only. Density is not a fixation or attention score.'}</div></div>${lesson()}<p class="small-note" id="regions"></p><div class="actions"><button class="solid" id="json">Export session JSON ↓</button><button class="secondary" id="csv">Raw samples CSV ↓</button><button class="secondary" id="again">New activity</button><button class="secondary" id="clear">Clear & disconnect</button></div><p class="fine">Heatmap shows samples within the activity. Region percentages use all scheduled samples, including missing data. Exports include viewport, quality flags and raw validation measurements.</p>`);$('#heatmap').hidden=false;drawHeatmap();$('#regions').textContent=['reading','diagram','outside activity','missing'].map(r=>`${r}: ${state.samples.length?Math.round(state.samples.filter(s=>s.region===r).length/state.samples.length*100):0}%`).join(' · ');$('#json').onclick=()=>download('json');$('#csv').onclick=()=>download('csv');$('#again').onclick=showValidationIntro;$('#clear').onclick=reset;message('○ Session complete · stored in memory');}
function drawHeatmap(){const c=$('#heatmap'),r=state.activityRect;c.width=r.width;c.height=r.height;const ctx=c.getContext('2d');for(const s of state.samples){if(!s.valid||s.activity_x<0||s.activity_x>r.width||s.activity_y<0||s.activity_y>r.height)continue;const x=s.activity_x,y=s.activity_y;const g=ctx.createRadialGradient(x,y,0,x,y,32);g.addColorStop(0,'rgba(201,86,50,.055)');g.addColorStop(.5,'rgba(219,153,61,.025)');g.addColorStop(1,'rgba(219,153,61,0)');ctx.fillStyle=g;ctx.fillRect(x-32,y-32,64,64);}}
function download(type){const report={schema:'faraday.observatory.v1',exportedAt:new Date().toISOString(),mode:state.mode,nonclinical:true,quality:state.mode==='pointer'?'rehearsal-not-gaze':state.validation?.pass?'provisional-pass':'low-quality',duration_ms:Math.round(state.elapsed),sampleIntervalTarget_ms:50,viewport:state.viewport,activityRect:state.activityRect,regions:state.regions,validation:state.validation,samples:state.samples,limitations:'Webcam estimates; not attention, comprehension, or clinical measurements. Pixel accuracy, not visual degrees. Missing samples retained. No video.'};const content=type==='json'?JSON.stringify(report,null,2):'mode,quality,t_ms,x,y,valid,offscreen,region\n'+state.samples.map(s=>[state.mode,report.quality,s.t_ms,s.x??'',s.y??'',s.valid,s.offscreen,s.region].join(',')).join('\n');const url=URL.createObjectURL(new Blob([content],{type:type==='json'?'application/json':'text/csv'}));const a=document.createElement('a');a.href=url;a.download=`faraday-${state.mode}-${Date.now()}.${type}`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function cancelTargets(){clearTimeout(targetTimer);activeValidation=null;$('#overlay').hidden=true;if(state.phase==='calibration')showCalibrationIntro();else showValidationIntro();}
$('#cancelTarget').onclick=cancelTargets;
function reset(){state.epoch++;clearTimeout(targetTimer);activeValidation=null;state.running=false;if(window.webgazer)webgazer.clearData();stopCamera();window.webgazer=undefined;trackerPromise=null;Object.assign(state,{mode:null,phase:'setup',latest:null,calibrated:false,validation:null,samples:[],elapsed:0});$('#overlay').hidden=true;$('#gazeDot').hidden=true;$('#modeBadge').textContent='NO SESSION';$('#source').textContent='Not connected';$('#calStatus').textContent='Not started';$('#accuracy').textContent='—';$('#sampleCount').textContent='0';message('○ Session cleared · camera disconnected');setup();}
window.addEventListener('resize',()=>{if(!state.mode)return;state.calibrated=false;state.validation=null;state.running=false;clearTimeout(targetTimer);activeValidation=null;$('#overlay').hidden=true;$('#accuracy').textContent='Invalidated';$('#calStatus').textContent='Window changed';showCalibrationIntro();message('○ Window changed · recalibrate');});
document.addEventListener('visibilitychange',()=>{if(document.hidden){if(!$('#overlay').hidden)cancelTargets();if(state.running)togglePause();}});
document.querySelectorAll('nav button').forEach(b=>b.onclick=()=>{if(state.running)togglePause();document.querySelectorAll('.view').forEach(v=>v.hidden=v.id!==b.dataset.view);document.querySelectorAll('nav button').forEach(x=>x.classList.toggle('active',x===b));});
window.addEventListener('beforeunload',stopCamera);
setup();state.raf=requestAnimationFrame(tick);
